pos":"noun","gloss":{"en":"lamp","ur":"چراغ"}}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000015","slug":"shaer","arab":"شاعر","latn":"shá'er","ipa":"/ʃɑː.ʔer/","added":"2026-11-05","senses":[{"pos":"noun","gloss":{"en":"poet","ur":"شاعر"}}],"relations":[{"type":"see_also","to":"sher"}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000016","slug":"sher","arab":"شعر","latn":"shé'r","added":"2026-11-06","senses":[{"pos":"noun","gloss":{"en":"poem, verse","ur":"شعر"}}],"relations":[{"type":"see_also","to":"shaer"}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000017","slug":"labz","arab":"لبز","latn":"labz","ipa":"/labz/","added":"2026-11-06","senses":[{"pos":"noun","gloss":{"en":"word","ur":"لفظ"}}],"relations":[{"type":"derived","to":"labzank"},{"type":"derived","to":"labzbald"}]},{"status":"draft","source":"labzank-editorial","type":"derived","id":"bal-000018","slug":"labzank","arab":"لبزانک","latn":"labzánk","root":"labz","added":"2026-11-07","senses":[{"pos":"noun","gloss":{"en":"literature","ur":"ادب"}}]},{"status":"draft","source":"labzank-editorial","type":"compound","id":"bal-000019","slug":"labzbald","arab":"لبزبلد","latn":"labzbald","root":"labz","added":"2026-11-07","senses":[{"pos":"noun","gloss":{"en":"dictionary","ur":"لغت"}}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000020","slug":"wanag","arab":"وانگ","latn":"wánag","added":"2026-11-08","senses":[{"pos":"verb","gloss":{"en":"to read; to study","ur":"پڑھنا"}}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000021","slug":"nebeshta","arab":"نبشتہ","latn":"nebeshta","added":"2026-11-08","senses":[{"pos":"noun","gloss":{"en":"writing, written text","ur":"تحریر"}}],"relations":[{"type":"derived","to":"nebeshtakar"}]},{"status":"draft","source":"labzank-editorial","type":"compound","id":"bal-000022","slug":"nebeshtakar","arab":"نبشتہ کار","latn":"nebeshtakár","root":"nebeshta","added":"2026-11-09","senses":[{"pos":"noun","gloss":{"en":"writer, author","ur":"مصنف، لکھاری"}}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000023","slug":"sart","arab":"سارت","latn":"sárt","ipa":"/sɑːrt/","added":"2026-11-09","senses":[{"pos":"adjective","gloss":{"en":"cold","ur":"ٹھنڈا"}}],"relations":[{"type":"antonym","to":"garm"}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000024","slug":"garm","arab":"گرم","latn":"garm","ipa":"/garm/","added":"2026-11-10","senses":[{"pos":"adjective","gloss":{"en":"hot, warm","ur":"گرم"}}],"relations":[{"type":"antonym","to":"sart"}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000025","slug":"mat","arab":"مات","latn":"mát","ipa":"/mɑːt/","added":"2026-11-10","senses":[{"pos":"noun","gloss":{"en":"mother","ur":"ماں"}}],"relations":[{"type":"see_also","to":"pet"}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000026","slug":"pet","arab":"پت","latn":"pet","ipa":"/pet/","added":"2026-11-11","senses":[{"pos":"noun","gloss":{"en":"father","ur":"باپ"}}],"relations":[{"type":"see_also","to":"mat"}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000027","slug":"dost","arab":"دوست","latn":"dóst","ipa":"/doːst/","added":"2026-11-11","senses":[{"pos":"noun","gloss":{"en":"friend","ur":"دوست"}}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000028","slug":"kaur","arab":"کئور","latn":"kaur","ipa":"/kawr/","added":"2026-11-12","senses":[{"pos":"noun","gloss":{"en":"river, seasonal stream","ur":"دریا، ندی"}}],"relations":[{"type":"see_also","to":"ap"}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000029","slug":"dod","arab":"دود","latn":"dód","added":"2026-11-13","senses":[{"pos":"noun","gloss":{"en":"custom, tradition","ur":"رسم، روایت"}}]},{"status":"draft","source":"labzank-editorial","type":"simple","id":"bal-000030","slug":"ganj","arab":"گنج","latn":"ganj","ipa":"/gandʒ/","added":"2026-11-14","senses":[{"pos":"noun","gloss":{"en":"treasure","ur":"خزانہ"}}]}],"wotd":[{"date":"2026-11-14","slug":"labzank"},{"date":"2026-11-15","slug":"gwat"},{"date":"2026-11-16","slug":"cherag"}]}$json$::jsonb; e jsonb; s jsonb; x jsonb; sid bigint; eid bigint; xid bigint; n int; k text; v text;
begin
  for k, v in select key, value::text from jsonb_each(d->'sources') loop
    insert into public.dict_sources (id, name, licence, attribution, url) values (k, (v::jsonb)->>'name', (v::jsonb)->>'licence', (v::jsonb)->>'attribution', (v::jsonb)->>'url') on conflict (id) do nothing;
  end loop;
  for e in select * from jsonb_array_elements(d->'entries') loop
    insert into public.dict_entries (slug, headword_arab, headword_latn, word_type, status, source_id, created_at)
    values (e->>'slug', e->>'arab', e->>'latn', (e->>'type')::public.dict_word_type, (e->>'status')::public.dict_status, e->>'source', (e->>'added')::timestamptz)
    returning id into eid;
    if e ? 'ipa' or e ? 'syllables' then
      insert into public.dict_pronunciations (entry_id, ipa, syllables)
      values (eid, e->>'ipa', case when e ? 'syllables' then array(select jsonb_array_elements_text(e->'syllables')) end);
    end if;
    n := 0;
    for s in select * from jsonb_array_elements(e->'senses') loop
      n := n + 1;
      insert into public.dict_senses (entry_id, n, pos) values (eid, n, s->>'pos') returning id into sid;
      for k, v in select key, value from jsonb_each_text(s->'gloss') loop
        insert into public.dict_glosses (sense_id, lang, text) values (sid, k, v);
      end loop;
      for x in select * from jsonb_array_elements(coalesce(s->'examples', '[]')) loop
        insert into public.dict_examples (sense_id, text_arab, text_latn, source_id) values (sid, x->>'arab', x->>'latn', e->>'source') returning id into xid;
        for k in select unnest(array['en','ur']) loop
          if x ? k then insert into public.dict_example_translations values (xid, k, x->>k); end if;
        end loop;
      end loop;
    end loop;
  end loop;
  for e in select * from jsonb_array_elements(d->'entries') loop
    if e ? 'root' then update public.dict_entries set root_entry_id = (select id from public.dict_entries where slug = e->>'root') where slug = e->>'slug'; end if;
    for x in select * from jsonb_array_elements(coalesce(e->'relations', '[]')) loop
      insert into public.dict_relations select f.id, t.id, (x->>'type')::public.dict_relation
      from public.dict_entries f, public.dict_entries t where f.slug = e->>'slug' and t.slug = x->>'to' on conflict do nothing;
    end loop;
  end loop;
  for x in select * from jsonb_array_elements(d->'wotd') loop
    insert into public.dict_word_of_day (day, entry_id) select (x->>'date')::date, id from public.dict_entries where slug = x->>'slug';
  end loop;
end $seed$;
